package fr.cake.client;
import java.util.*;import org.joml.Matrix4f;import org.joml.Vector3f;import com.mojang.blaze3d.vertex.PoseStack;import net.minecraft.client.renderer.SubmitNodeCollector;import net.minecraft.client.renderer.rendertype.RenderTypes;import net.minecraft.resources.Identifier;import net.minecraft.client.renderer.texture.OverlayTexture;
public final class KnifeTrail{
 private record Sample(Vector3f tip,Vector3f root,long at){}private static final ArrayDeque<Sample> samples=new ArrayDeque<>();private static int tipPart=-1,tipVertex;private static Knives.NativeMesh[] cached;private static long last;
 public static void clear(){samples.clear();tipPart=-1;cached=null;}
 public static void submit(PoseStack stack,SubmitNodeCollector collector,Knives.NativeMesh[] meshes,Matrix4f[] pose,Matrix4f base,Matrix4f hand,boolean active){var s=CakeClient.settings;if(!s.knifeTrails){samples.clear();return;}long now=System.nanoTime();long life=(long)((.06+s.knifeTrailLife*.28)*1e9);samples.removeIf(p->now-p.at>life);
  if(cached!=meshes){clear();cached=meshes;float far=-1;var grip=hand.getTranslation(new Vector3f());for(int part=0;part<meshes.length;part++){float[] d=meshes[part].data();for(int v=0;v<meshes[part].count();v++){var p=pose[part].transformPosition(new Vector3f(d[v*8],d[v*8+1],d[v*8+2]));float dist=p.distanceSquared(grip);if(dist>far){far=dist;tipPart=part;tipVertex=v;}}}}
  if(active&&tipPart>=0&&now-last>5_000_000){last=now;float[] d=meshes[tipPart].data();int i=tipVertex*8;var tip=new Matrix4f(base).mul(pose[tipPart]).transformPosition(new Vector3f(d[i],d[i+1],d[i+2]));var grip=new Matrix4f(base).mul(hand).getTranslation(new Vector3f());samples.add(new Sample(tip,new Vector3f(grip).lerp(tip,.55f),now));while(samples.size()>28)samples.removeFirst();}
  if(samples.size()<2)return;var points=samples.toArray(Sample[]::new);int rgb=java.awt.Color.HSBtoRGB((float)s.knifeTrailHue,.45f,1);var type=RenderTypes.entityTranslucent(Identifier.fromNamespaceAndPath("cakeclient","textures/knife-trail.png"));collector.submitCustomGeometry(stack,type,(transform,v)->{for(int j=1;j<points.length;j++){var a=points[j-1];var b=points[j];var ps=new Vector3f[]{a.root,a.tip,b.tip,b.root};for(int k=0;k<4;k++){var p=transform.pose().transformPosition(new Vector3f(ps[k]));float fade=(float)Math.max(0,1-(now-(k<2?a.at:b.at))/(double)life);v.addVertex(p.x,p.y,p.z).setUv(k==0||k==3?0:1,k<2?0:1).setColor((rgb>>16)&255,(rgb>>8)&255,rgb&255,(int)(fade*140)).setOverlay(OverlayTexture.NO_OVERLAY).setLight(0xF000F0).setNormal(0,0,1);}}});
 }
}
